// client/src/features/dashboard/attendee/AttendeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get(
        '/api/attendee/events',                // ← relative URL
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setEvents(res.data.events);
      setError(null);
    } catch (err) {
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchEvents(); }, []);

  const handleRegister = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        '/api/attendee/register',              // ← relative URL
        { eventId: id },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Registration failed');
    }
  };

  const handlePay = async (id) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `/api/attendee/pay/${id}`,             // ← relative URL
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch {
      alert('Payment failed');
    }
  };

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {loading ? (
          <p>Loading…</p>
        ) : error ? (
          <p style={{ color:'red' }}>{error}</p>
        ) : (
          <ul style={{ listStyle: 'none', padding: 0 }}>
            {events.map(evt => (
              <li key={evt.id} style={{ margin: '1rem 0' }}>
                <strong>{evt.title}</strong> — {new Date(evt.date).toLocaleString()}
                <br/>
                {!evt.isRegistered && (
                  <button className="btn" onClick={() => handleRegister(evt.id)}>
                    Register
                  </button>
                )}
                {evt.isRegistered && !evt.hasPaid && (
                  <button className="btn" onClick={() => handlePay(evt.id)}>
                    Pay Now
                  </button>
                )}
                {evt.hasPaid && (
                  <a
                    href={evt.sessionLink}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="btn"
                  >
                    Join Session
                  </a>
                )}
              </li>
            ))}
            {events.length === 0 && <p>No events available.</p>}
          </ul>
        )}
      </div>
    </div>
  );
};

export default AttendeeDashboard;
